3	// Regression tests for GET /ledger/verify:
4	//
5	//   - an empty ledger and a complete, append-built chain report valid with
6	//     checked equal to the record count and first_invalid_seq null;
7	//   - any query string is rejected with 400 invalid_audit_input before the
8	//     store is touched;
9	//   - the first broken position stops the pass: a seq gap reports the
10	//     expected seq, a broken back-link or self-hash reports the record seq,
11	//     and checked includes the triggering record;
12	//   - verification never repairs stored values;
13	//   - passes racing concurrent appends see one committed snapshot each and
14	//     never report a false break;
15	//   - storage failure maps to 503 storage_unavailable with no partial body.
16	
17	import (
18		"database/sql"
19		"encoding/json"
20		"fmt"
21		"net/http"
22		"net/http/httptest"
