135			"time bad shape":      `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05 00:00:00Z"}`,
136			"seq fraction":        `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":1.5}`,
