169	func TestPostEventExplicitSeq(t *testing.T) {
170		router := NewRouter(openTestStore(t))
171	
172		// Explicit seq equal to the next sequence number is accepted.
173		body := `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":1}`
174		if recorder := postEventBody(t, router, body); recorder.Code != http.StatusCreated {
175			t.Fatalf("explicit next seq: status = %d (%s)", recorder.Code, recorder.Body.String())
176		}
177	
178		// An existing seq conflicts.
179		if recorder := postEventBody(t, router, body); recorder.Code != http.StatusConflict {
180			t.Fatalf("existing seq: status = %d, want 409 (%s)", recorder.Code, recorder.Body.String())
181		} else if event := decodeEvent(t, recorder); event["error"].(map[string]any)["code"] != "audit_seq_conflict" {
182			t.Fatalf("existing seq: code = %v", event)
183		}
184	
185		// A seq past the next one is rejected as invalid input.
186		gap := `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":5}`
187		recorder := postEventBody(t, router, gap)
188		if recorder.Code != http.StatusBadRequest {
189			t.Fatalf("gap seq: status = %d, want 400 (%s)", recorder.Code, recorder.Body.String())
190		}
191		if event := decodeEvent(t, recorder); event["error"].(map[string]any)["code"] != "invalid_audit_input" {
192			t.Fatalf("gap seq: body = %v", event)
193		}
194	
195		// Failed appends consume no sequence number: the next append is seq 2.
196		recorder = postEventBody(t, router, validEventBody())
197		if recorder.Code != http.StatusCreated {
198			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
199		}
200		if event := decodeEvent(t, recorder); event["seq"] != float64(2) {
201			t.Fatalf("seq = %v, want 2 after failed appends", event["seq"])
202		}
203	}
