376		path := filepath.Join(t.TempDir(), "service.db")
377		st, err := store.Open(path)
378		if err != nil {
379			t.Fatalf("open: %v", err)
380		}
381		defer st.Close()
382		router := NewRouter(st)
383	
384		cases := []struct {
385			occurredAt string
386			wantUTC    string
387		}{
388			// One minute inside the lower bound: UTC lands exactly on 0000-01-01T00:00:00Z.
389			{"0000-01-01T00:01:00+00:01", "0000-01-01T00:00:00Z"},
390			// One minute inside the upper bound: UTC lands exactly on 9999-12-31T23:59:59Z.
391			{"9999-12-31T23:58:59-00:01", "9999-12-31T23:59:59Z"},
392		}
393		prevHash := strings.Repeat("0", 64)
394		for i, tc := range cases {
395			recorder := postEventBody(t, router,
396				fmt.Sprintf(`{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":%q}`, tc.occurredAt))
397			if recorder.Code != http.StatusCreated {
398				t.Fatalf("%s: status = %d (%s)", tc.occurredAt, recorder.Code, recorder.Body.String())
399			}
