638		}
639		second := decodeEvent(t, recorder)
640		if second["seq"] != float64(2) || second["prev_hash"] != first["hash"] {
641			t.Fatalf("next = %v, want seq 2 chained to %v", second, first["hash"])
642		}
643		stored = readStoredEvents(t, path)
