package store

import "errors"

// ErrInjectedRead is the failure the regression tests inject into a read in
// progress. It models a storage layer that is still connected (Ping keeps
// succeeding) but returns an error while a query is being scanned or iterated.
var ErrInjectedRead = errors.New("injected read failure")

// readFaultHook is nil outside tests. When set, it is consulted after every
// successfully scanned row during a ledger read, receiving the 1-based ordinal
// of that row within the current pass. Returning an error fails the read at
// exactly that point; rows already scanned stay inside the read transaction
// and never reach the API response. The hook never affects Ping or writes.
var readFaultHook func(rowsRead int) error

// faultAfterRows installs a read fault that fires once the pass has scanned
// ordinal+1 rows (i.e. after a valid prefix of that length).
func faultAfterRows(ordinal int) {
	readFaultHook = func(rowsRead int) error {
		if rowsRead > ordinal {
			return ErrInjectedRead
		}
		return nil
	}
}

// clearReadFault removes any installed read fault.
func clearReadFault() {
	readFaultHook = nil
}

