}

func clearInstalledReadFault() { readFaultHook = nil }

// assertBareError asserts the published error contract: exactly one top-level
// "error" object holding precisely code and a non-empty message, with no
// internal detail leaked into the body.
func assertBareError(t *testing.T, recorder *httptest.ResponseRecorder, wantStatus int, wantCode string) {
	t.Helper()
