		t.Fatalf("status = %d, want %d (%s)", recorder.Code, wantStatus, recorder.Body.String())
	}
	body := recorder.Body.Bytes()

	var top map[string]json.RawMessage
	if err := json.Unmarshal(body, &top); err != nil {
		t.Fatalf("decode error body: %v (%s)", err, body)
	}
	if len(top) != 1 {
		t.Fatalf("response keys = %v, want only the error object", top)
	}
	rawError, ok := top["error"]
	if !ok {
		t.Fatalf("body has no error object: %s", body)
	}
	var inner map[string]json.RawMessage
	if err := json.Unmarshal(rawError, &inner); err != nil {
		t.Fatalf("decode error object: %v (%s)", err, body)
	}
