287	func recordOf(fx eventFixture) ledgerRecord {
288		return ledgerRecord{
289			account:    fx.req.Account,
290			operation:  fx.req.Operation,
291			resource:   fx.req.Resource,
292			result:     fx.req.Result,
293			occurredAt: fx.occurredUTC,
294		}
