297	func TestPostEventConcurrentAppendsPersistFullChain(t *testing.T) {
298		path := filepath.Join(t.TempDir(), "service.db")
299		st := openStoreAt(t, path)
300		router := NewRouter(st)
301		fixtures := concurrentFixtures()
302	
303		// Fire all requests at the same instant on the one service instance.
304		// Completion order is deliberately not assumed to be seq order: every
305		// assertion below maps responses back through the response's seq.
306		start := make(chan struct{})
307		recorders := make([]*httptest.ResponseRecorder, len(fixtures))
308		var wg sync.WaitGroup
309		for i := range fixtures {
310			wg.Add(1)
311			go func(i int) {
312				defer wg.Done()
313				<-start
314				recorders[i] = postStructuredEvent(t, router, fixtures[i].req)
315			}(i)
316		}
317		close(start)
318		wg.Wait()
319	
320		createdBySeq := map[int64]createdEvent{}
321		wantBySeq := map[int64]ledgerRecord{}
322		for i, recorder := range recorders {
323			if recorder.Code != http.StatusCreated {
324				t.Fatalf("request %d: status = %d, want 201 (%s)", i, recorder.Code, recorder.Body.String())
325			}
326			got := decodeCreated(t, recorder)
327			fx := fixtures[i]
328			if got.Seq < 1 || got.Seq > int64(len(fixtures)) {
329				t.Fatalf("request %d: seq = %d outside 1..%d", i, got.Seq, len(fixtures))
330			}
331			if _, exists := createdBySeq[got.Seq]; exists {
332				t.Fatalf("seq %d handed out more than once", got.Seq)
333			}
334			// The response carries the submitting request's own fields, stored
335			// verbatim, with occurred_at normalized to UTC (fraction kept).
336			if got.Account != fx.req.Account || got.Operation != fx.req.Operation ||
337				got.Resource != fx.req.Resource || got.Result != fx.req.Result {
338				t.Fatalf("request %d: saved business fields %+v, want %+v", i, got, fx.req)
339			}
340			if got.OccurredAt != fx.occurredUTC {
341				t.Fatalf("request %d: occurred_at = %q, want %q", i, got.OccurredAt, fx.occurredUTC)
342			}
343			// Hash is recomputed independently from the public JSON-array rule.
344			if want := wantHash(got.Seq, fx.req.Account, fx.req.Operation, fx.req.Resource,
345				fx.req.Result, fx.occurredUTC, got.PrevHash); got.Hash != want {
346				t.Fatalf("request %d: hash = %s, want %s", i, got.Hash, want)
347			}
348			createdBySeq[got.Seq] = got
349			wantBySeq[got.Seq] = recordOf(fx)
350		}
351	
352		// Every request was saved exactly once, with contiguous seqs from 1 and
353		// proper prev_hash linkage, regardless of completion order.
354		responseHash := map[int64]string{}
355		want := make([]ledgerRecord, len(fixtures))
356		prev := strings.Repeat("0", 64)
357		for seq := int64(1); seq <= int64(len(fixtures)); seq++ {
358			got, ok := createdBySeq[seq]
359			if !ok {
360				t.Fatalf("seq %d missing from responses", seq)
361			}
362			if got.PrevHash != prev {
363				t.Fatalf("seq %d prev_hash = %s, want %s", seq, got.PrevHash, prev)
364			}
365			if got.Hash != wantHash(seq, wantBySeq[seq].account, wantBySeq[seq].operation,
366				wantBySeq[seq].resource, wantBySeq[seq].result, wantBySeq[seq].occurredAt, prev) {
367				t.Fatalf("seq %d hash does not verify against the public rule", seq)
368			}
369			prev = got.Hash
370			responseHash[seq] = got.Hash
371			want[seq-1] = wantBySeq[seq]
372		}
373		tail := prev
374	
375		// Close, then read the file through an independent connection: the
376		// persisted rows match the successful responses one for one.
377		closeStore(t, st)
378		verifyLedger(t, path, want, responseHash)
379	
380		// Reopen: the same chain is visible and the next auto-seq append
381		// continues immediately after the old tail.
382		st = openStoreAt(t, path)
383		recorder := postEventBody(t, NewRouter(st), validEventBody())
384		if recorder.Code != http.StatusCreated {
385			t.Fatalf("append after reopen: status = %d (%s)", recorder.Code, recorder.Body.String())
386		}
387		after := decodeCreated(t, recorder)
388		if after.Seq != int64(len(fixtures)+1) || after.PrevHash != tail {
389			t.Fatalf("after reopen: seq = %d prev_hash = %s, want %d and %s",
390				after.Seq, after.PrevHash, len(fixtures)+1, tail)
391		}
392		want = append(want, ledgerRecord{
393			account: "alice", operation: "login", resource: "console", result: "ok",
394			occurredAt: "2026-10-05T00:30:00Z",
395		})
396		responseHash[after.Seq] = after.Hash
397		closeStore(t, st)
398	
399		// Full records and verification chain are re-checked after close/reopen.
400		verifyLedger(t, path, want, responseHash)
401	}
402	
403	func TestPostEventExplicitSeqRaceElectsSingleWinner(t *testing.T) {
404		path := filepath.Join(t.TempDir(), "service.db")
405		st := openStoreAt(t, path)
406		router := NewRouter(st)
407	
408		const contenders = 8
409		fixtures := make([]eventFixture, contenders)
410		for i := 0; i < contenders; i++ {
411			seq := int64(1) // every contender races for the same legal next seq
412			marker := string(rune('a' + i))
413			fixtures[i] = eventFixture{
414				req: eventRequest{
415					Account:    "racer-" + marker,
416					Operation:  "op-" + marker,
417					Resource:   "resource-" + marker,
418					Result:     []string{"ok", "denied"}[i%2],
419					OccurredAt: "2026-10-05T00:00:0" + string(rune('0'+i)) + "Z",
420					Seq:        &seq,
421				},
422				occurredUTC: "2026-10-05T00:00:0" + string(rune('0'+i)) + "Z",
423			}
424		}
425	
426		start := make(chan struct{})
427		recorders := make([]*httptest.ResponseRecorder, contenders)
428		var wg sync.WaitGroup
429		for i := range fixtures {
430			wg.Add(1)
431			go func(i int) {
432				defer wg.Done()
433				<-start
434				recorders[i] = postStructuredEvent(t, router, fixtures[i].req)
435			}(i)
436		}
437		close(start)
438		wg.Wait()
439	
440		winners := 0
441		var winner createdEvent
442		var winnerIndex int
443		for i, recorder := range recorders {
444			switch recorder.Code {
445			case http.StatusCreated:
446				winners++
447				winner = decodeCreated(t, recorder)
448				winnerIndex = i
449			case http.StatusConflict:
450				assertErrorEnvelope(t, recorder, http.StatusConflict, "audit_seq_conflict")
451			default:
452				t.Fatalf("contender %d: status = %d, want 201 or 409 (%s)", i, recorder.Code, recorder.Body.String())
453			}
454		}
455		if winners != 1 {
456			t.Fatalf("winners = %d, want exactly 1", winners)
457		}
458		winnerFX := fixtures[winnerIndex]
459	
460		// The unique winner occupies seq 1 with its own content.
461		if winner.Seq != 1 || winner.PrevHash != strings.Repeat("0", 64) {
462			t.Fatalf("winner = %+v, want seq 1 chained to genesis", winner)
463		}
464		if winner.Account != winnerFX.req.Account || winner.Operation != winnerFX.req.Operation ||
465			winner.Resource != winnerFX.req.Resource || winner.Result != winnerFX.req.Result ||
466			winner.OccurredAt != winnerFX.occurredUTC {
467			t.Fatalf("winner fields = %+v, want %+v", winner, winnerFX.req)
468		}
469		if want := wantHash(1, winnerFX.req.Account, winnerFX.req.Operation, winnerFX.req.Resource,
470			winnerFX.req.Result, winnerFX.occurredUTC, winner.PrevHash); winner.Hash != want {
471			t.Fatalf("winner hash = %s, want %s", winner.Hash, want)
472		}
473	
474		if recorder := getHealthz(t, router); recorder.Code != http.StatusOK {
475			t.Fatalf("healthz after race: status = %d (%s)", recorder.Code, recorder.Body.String())
476		}
477	
478		loserAccounts := map[string]bool{}
479		for i, fx := range fixtures {
480			if i != winnerIndex {
481				loserAccounts[fx.req.Account] = true
482			}
483		}
484	
485		closeStore(t, st)
486		// Only the winner's record exists.
487		events := verifyLedger(t, path, []ledgerRecord{recordOf(winnerFX)},
488			map[int64]string{1: winner.Hash})
489		assertAccountsAbsent(t, events, loserAccounts)
490	
491		// After the race the next auto-seq append takes seq 2 and chains to the
492		// winner; the losing requests left nothing behind.
493		st = openStoreAt(t, path)
494		next := eventFixture{
495			req: eventRequest{
496				Account: "after-race", Operation: "followup", Resource: "console", Result: "ok",
497				OccurredAt: "2026-10-05T03:45:00+03:00",
498			},
499			occurredUTC: "2026-10-05T00:45:00Z",
500		}
501		recorder := postStructuredEvent(t, NewRouter(st), next.req)
502		if recorder.Code != http.StatusCreated {
503			t.Fatalf("append after race: status = %d (%s)", recorder.Code, recorder.Body.String())
504		}
505		followup := decodeCreated(t, recorder)
506		if followup.Seq != 2 || followup.PrevHash != winner.Hash {
507			t.Fatalf("after race: seq = %d prev_hash = %s, want 2 and %s", followup.Seq, followup.PrevHash, winner.Hash)
508		}
509		if followup.Account != next.req.Account || followup.OccurredAt != next.occurredUTC {
510			t.Fatalf("after race: response = %+v, want %+v", followup, next.req)
511		}
512		closeStore(t, st)
513	
514		events = verifyLedger(t, path,
515			[]ledgerRecord{recordOf(winnerFX), recordOf(next)},
516			map[int64]string{1: winner.Hash, 2: followup.Hash})
517		assertAccountsAbsent(t, events, loserAccounts)
518	}
519	
520	func TestPostEventControlledWriteFailureLeavesChainUntouched(t *testing.T) {
521		path := filepath.Join(t.TempDir(), "service.db")
522		st := openStoreAt(t, path)
523		router := NewRouter(st)
524	
525		// Seed two committed records and snapshot the chain tail.
526		seeds := []eventFixture{
527			{eventRequest{Account: "alice", Operation: "login", Resource: "console", Result: "ok", OccurredAt: "2026-10-05T08:30:00+08:00"}, "2026-10-05T00:30:00Z"},
528			{eventRequest{Account: "bob", Operation: "read", Resource: "report", Result: "denied", OccurredAt: "2026-10-05T01:00:00.250Z"}, "2026-10-05T01:00:00.250Z"},
529		}
530		want := []ledgerRecord{}
531		responseHash := map[int64]string{}
532		prev := strings.Repeat("0", 64)
533		for i, fx := range seeds {
534			recorder := postStructuredEvent(t, router, fx.req)
535			if recorder.Code != http.StatusCreated {
536				t.Fatalf("seed %d: status = %d (%s)", i, recorder.Code, recorder.Body.String())
537			}
538			got := decodeCreated(t, recorder)
539			if got.Seq != int64(i+1) || got.PrevHash != prev {
540				t.Fatalf("seed %d = %+v, want seq %d chained to %s", i, got, i+1, prev)
541			}
542			if got.OccurredAt != fx.occurredUTC {
543				t.Fatalf("seed %d occurred_at = %q", i, got.OccurredAt)
544			}
545			if h := wantHash(got.Seq, fx.req.Account, fx.req.Operation, fx.req.Resource,
546				fx.req.Result, fx.occurredUTC, got.PrevHash); got.Hash != h {
547				t.Fatalf("seed %d hash = %s, want %s", i, got.Hash, h)
548			}
549			prev = got.Hash
550			responseHash[got.Seq] = got.Hash
551			want = append(want, recordOf(fx))
552		}
553		tail := prev
554	
555		// Make every INSERT fail while the database stays readable. This is
556		// deliberately different from the closed-handle scenario covered
557		// elsewhere: /healthz must still report ok during the failure.
558		setInsertFailure(t, path, true)
559		if recorder := getHealthz(t, router); recorder.Code != http.StatusOK {
560			t.Fatalf("healthz during write failure: status = %d (%s)", recorder.Code, recorder.Body.String())
561		}
562	
563		failed := eventRequest{Account: "never-saved", Operation: "write", Resource: "bucket",
564			Result: "error", OccurredAt: "2026-10-05T02:00:00Z"}
565		recorder := postStructuredEvent(t, router, failed)
566		assertErrorEnvelope(t, recorder, http.StatusServiceUnavailable, "storage_unavailable")
567	
568		// Existing records, count and chain tail are exactly as before the failure.
569		events := verifyLedger(t, path, want, responseHash)
570		if events[len(events)-1].hash != tail {
571			t.Fatalf("tail hash = %s after failed write, want %s", events[len(events)-1].hash, tail)
572		}
573		assertAccountsAbsent(t, events, map[string]bool{failed.Account: true})
574	
575		// Restore writes: the next append takes the original next seq and chains
576		// onto the unchanged tail.
577		setInsertFailure(t, path, false)
578		if recorder := getHealthz(t, router); recorder.Code != http.StatusOK {
579			t.Fatalf("healthz after recovery: status = %d (%s)", recorder.Code, recorder.Body.String())
580		}
581		recovery := eventFixture{
582			req: eventRequest{Account: "carol", Operation: "retry", Resource: "console",
583				Result: "ok", OccurredAt: "2026-10-05T03:45:00+03:00"},
584			occurredUTC: "2026-10-05T00:45:00Z",
585		}
586		recorder = postStructuredEvent(t, router, recovery.req)
587		if recorder.Code != http.StatusCreated {
588			t.Fatalf("append after recovery: status = %d (%s)", recorder.Code, recorder.Body.String())
589		}
590		got := decodeCreated(t, recorder)
591		if got.Seq != int64(len(seeds)+1) || got.PrevHash != tail {
592			t.Fatalf("after recovery: seq = %d prev_hash = %s, want %d and %s",
593				got.Seq, got.PrevHash, len(seeds)+1, tail)
594		}
595		wantAfterRecovery := append(append([]ledgerRecord{}, want...), recordOf(recovery))
596		responseHash[got.Seq] = got.Hash
597		closeStore(t, st)
598		events = verifyLedger(t, path, wantAfterRecovery, responseHash)
599		assertAccountsAbsent(t, events, map[string]bool{failed.Account: true})
600	
601		// After a close/reopen the full chain is intact and still grows, and the
602		// failed request remains absent.
603		st = openStoreAt(t, path)
604		afterReopen := eventFixture{
605			req: eventRequest{Account: "dave", Operation: "verify", Resource: "audit-log",
606				Result: "ok", OccurredAt: "2026-10-05T00:00:00.5Z"},
607			occurredUTC: "2026-10-05T00:00:00.5Z",
608		}
609		recorder = postStructuredEvent(t, NewRouter(st), afterReopen.req)
610		if recorder.Code != http.StatusCreated {
611			t.Fatalf("append after reopen: status = %d (%s)", recorder.Code, recorder.Body.String())
612		}
613		got = decodeCreated(t, recorder)
614		if got.Seq != int64(len(seeds)+2) || got.PrevHash != responseHash[int64(len(seeds)+1)] {
615			t.Fatalf("after reopen: seq = %d prev_hash = %s", got.Seq, got.PrevHash)
616		}
617		wantFinal := append(append([]ledgerRecord{}, wantAfterRecovery...), recordOf(afterReopen))
618		responseHash[got.Seq] = got.Hash
619		closeStore(t, st)
620	
621		events = verifyLedger(t, path, wantFinal, responseHash)
622		assertAccountsAbsent(t, events, map[string]bool{failed.Account: true})
623	}
