func recordOf(fx eventFixture) ledgerRecord {
	return ledgerRecord{
		account:    fx.req.Account,
		operation:  fx.req.Operation,
		resource:   fx.req.Resource,
		result:     fx.req.Result,
		occurredAt: fx.occurredUTC,
	}
